/**
 * Test flow for Repeat trigger
 * Tests: Repeat scheduled trigger with duration interval
 */

import { action, Flow, wfa, trigger } from '@servicenow/sdk/automation'

export const testRepeatTriggerMandatoryOnly = Flow(
    {
        $id: Now.ID['test_repeat_trigger_flow'],
        name: 'Test Repeat Trigger',
        description: 'Tests the Repeat trigger running at specified intervals',
    },
    wfa.trigger(
        trigger.scheduled.repeat,
        { $id: Now.ID['test_repeat_trigger'] },
        {
            repeat: Duration({
                days: 11,
                hours: 11,
                minutes: 11,
                seconds: 11,
            }),
        }
    ),
    (_params) => {
        // Log trigger outputs
        wfa.action(
            action.core.log,
            { $id: Now.ID['test_repeat_trigger_log_mandatory_only'] },
            {
                log_level: 'info',
                log_message: `Repeat Trigger - Run Start Time: ${wfa.dataPill(_params.trigger.run_start_time, 'glide_date_time')}, Run Start Date/Time: ${wfa.dataPill(_params.trigger.run_start_date_time, 'glide_date_time')}`,
            }
        )
    }
)

